const $=id=>document.getElementById(id), fmt=new Intl.NumberFormat('nl-NL'), eur=new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',maximumFractionDigits:0});
let people=[],page=0,selected=null,worker=null,result=null,revision=0,cancelResolve=null;const size=50;
function generate(n){return Array.from({length:n},(_,i)=>({name:`Persoon ${String(i+1).padStart(5,'0')}`,income:36000+(i*7919%60000),cost:24000+(i*3571%22000)}))}
function settings(){const out={};for(const id of ['count','scenarios','years','growth','inflation','discount','spread']){const el=$(id);if(!el.checkValidity()||el.value==='')throw Error('Controleer de modelinstellingen.');out[id]=Number(el.value)}for(const k of ['count','scenarios','years'])if(!Number.isInteger(out[k]))throw Error('Personen, scenario’s en jaren moeten gehele getallen zijn.');if(out.count*out.scenarios*out.years>300000000)throw Error('Kies maximaal 300 miljoen rekenstappen per berekening.');return out}
function invalidate(){revision++;result=null;$('npv').textContent='—';$('time').textContent='—';$('speed').textContent='Opnieuw doorrekenen';$('resultstate').textContent='Invoer gewijzigd';$('chart').innerHTML='<div class="empty">Reken opnieuw door voor actuele resultaten.</div>';$('bounds').textContent='';$('export').disabled=true}
function render(){const start=page*size;$('rows').replaceChildren();people.slice(start,start+size).forEach((p,j)=>{const tr=document.createElement('tr');const num=document.createElement('td');num.textContent=start+j+1;tr.append(num);['name','income','cost'].forEach((key,col)=>{const td=document.createElement('td'),input=document.createElement('input');input.value=p[key];input.setAttribute('aria-label',`${key} persoon ${start+j+1}`);input.type=col?'number':'text';input.step='any';input.onfocus=()=>{selected={input,p,key};$('cellref').textContent=String.fromCharCode(65+col)+(start+j+1);$('formula').value=input.value};input.onchange=()=>{if(col&&(!Number.isFinite(Number(input.value))||Math.abs(Number(input.value))>1e12||input.value==='')){input.value=p[key];return}p[key]=col?Number(input.value):input.value;$('formula').value=input.value;tr.lastChild.textContent=eur.format(p.income-p.cost);invalidate()};td.append(input);tr.append(td)});const td=document.createElement('td');td.textContent=eur.format(p.income-p.cost);tr.append(td);$('rows').append(tr)});$('range').textContent=`${fmt.format(start+1)}–${fmt.format(Math.min(start+size,people.length))} van ${fmt.format(people.length)} personen`;$('prev').disabled=page===0;$('next').disabled=start+size>=people.length;$('dataset').textContent=`${fmt.format(people.length)} personen · bewerk of plak je eigen data`;selected=null}
$('formula').onchange=()=>{if(selected){selected.input.value=$('formula').value;selected.input.dispatchEvent(new Event('change'))}};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};
for(const id of ['count','scenarios','years','growth','inflation','discount','spread'])$(id).onchange=()=>{invalidate();try{const s=settings();if(id==='count'){if(s.count>people.length)people=people.concat(generate(s.count-people.length).map((p,i)=>({...p,name:`Persoon ${people.length+i+1}`})));else people.length=s.count;page=0;render()}$('volume').textContent=fmt.format(s.count*s.scenarios*s.years);invalidate();$('status').textContent='Instellingen gewijzigd. Klaar om opnieuw te rekenen.'}catch(e){$('status').textContent=e.message}};
function chart(r){const curves=[r.low,r.base,r.high],values=curves.flat();let min=Math.min(0,...values),max=Math.max(0,...values);if(max===min)max=min+1;const x=i=>60+i/Math.max(1,r.base.length-1)*750,y=v=>170-(v-min)/(max-min)*150;let svg='<svg viewBox="0 0 840 210" role="img" aria-label="Totale jaarlijkse kasstroom voor lage groei, basis en hoge groei">';for(let i=0;i<4;i++){let v=min+(max-min)*i/3;svg+=`<line x1="60" y1="${y(v)}" x2="810" y2="${y(v)}" stroke="#e8eee8"/><text x="50" y="${y(v)+4}" text-anchor="end" fill="#809083" font-size="11">${(v/1e6).toLocaleString('nl-NL',{maximumFractionDigits:1})}m</text>`}curves.forEach((c,i)=>{svg+=`<polyline points="${c.map((v,j)=>`${x(j)},${y(v)}`).join(' ')}" fill="none" stroke="${['#a3c3b6','#143f3b','#b3d844'][i]}" stroke-width="${i===1?3:2}"/>`});svg+='<text x="60" y="200" fill="#809083" font-size="12">Jaar 1</text>';svg+=`<text x="810" y="200" text-anchor="end" fill="#809083" font-size="12">Jaar ${r.base.length}</text></svg>`;$('chart').innerHTML=svg}
function run(){if(worker){worker.terminate();worker=null;cancelResolve?.({cancelled:true});cancelResolve=null;$('run').textContent='▶  Alles doorrekenen';$('status').textContent='Berekening gestopt.';return Promise.resolve({cancelled:true})}let s;try{s=settings();if(s.count!==people.length)throw Error('Bevestig het aantal personen eerst met Enter.')}catch(e){$('status').textContent=e.message;return Promise.reject(e)}const rev=revision;$('run').textContent='■  Berekening stoppen';$('status').textContent='Scenario’s doorrekenen… Je kunt het werkblad blijven gebruiken.';const data=new Float64Array(people.length*2);people.forEach((p,i)=>{data[2*i]=p.income;data[2*i+1]=p.cost});worker=new Worker('worker.js',{type:'module'});return new Promise((resolve,reject)=>{cancelResolve=resolve;worker.onmessage=({data:r})=>{if(r.progress!==undefined){$('status').textContent=`Scenario’s doorrekenen… ${r.progress}%`;return}worker.terminate();worker=null;$('run').textContent='▶  Alles doorrekenen';if(rev!==revision){$('status').textContent='Invoer tijdens berekening gewijzigd. Reken opnieuw door.';resolve({stale:true});return}result=r;$('npv').textContent=eur.format(r.baseNpv);$('time').textContent=(r.ms/1000).toLocaleString('nl-NL',{maximumFractionDigits:3})+' s';$('speed').textContent='Gemeten rekentijd';$('resultstate').textContent=`${fmt.format(s.scenarios)} scenario’s berekend`;chart(r);$('bounds').textContent=`Contante waarde lage groei: ${eur.format(r.lowNpv)}  ·  Hoge groei: ${eur.format(r.highNpv)}`;$('export').disabled=false;$('status').textContent=`Gereed · ${fmt.format(s.count*s.scenarios*s.years)} scenario-rekenstappen + basisscenario · ${fmt.format(s.count)} personen.`;resolve({ms:r.ms,baseNpv:r.baseNpv,scenarios:s.scenarios})};worker.onerror=()=>{worker.terminate();worker=null;$('run').textContent='▶  Alles doorrekenen';$('status').textContent='Berekening mislukt. Probeer een kleiner model.';reject(Error('Berekening mislukt'))};worker.postMessage({s,data},[data.buffer])})}
$('run').onclick=()=>run().catch(()=>{});$('export').disabled=true;$('export').onclick=()=>{if(!result)return;const rows=[['scenario','groei_pct','contante_waarde'],...result.scenarios.map((v,i)=>[i+1,v.growth,v.npv])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(v=>typeof v==='number'?String(v).replace('.',','):v).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kasstroom-scenarios.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('paste').onclick=()=>$('pasteDialog').showModal();$('applyPaste').onclick=()=>{try{const lines=$('pasteData').value.trim().split(/\r?\n/);if(lines.length>100000)throw Error('Maximaal 100.000 personen.');const parsed=lines.map((line,i)=>{const cols=line.split('\t');const num=s=>Number(s.trim().replace(',','.'));if(cols.length!==3||!cols[0].trim()||cols.slice(1).some(v=>!v.trim()||!Number.isFinite(num(v))||Math.abs(num(v))>1e12))throw Error(`Controleer regel ${i+1}: drie kolommen, met twee geldige getallen.`);return {name:cols[0],income:num(cols[1]),cost:num(cols[2])}});people=parsed;$('count').value=people.length;page=0;render();invalidate();$('volume').textContent=fmt.format(people.length*Number($('scenarios').value)*Number($('years').value));$('pasteDialog').close();$('status').textContent='Eigen gegevens ingelezen. Klaar om door te rekenen.'}catch(e){$('pasteError').textContent=e.message}};
people=generate(10000);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'calculate_cashflow_scenarios',description:'Bereken de huidige personen en instellingen; retourneert de contante waarde en gemeten rekentijd.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||Object.keys(input).length)throw Error('Geen parameters toegestaan');if(worker)throw Error('Berekening loopt al');return run()}})).catch(()=>{})}catch{}}
